              $(document).ready(function () {
                $(".post-thumb-s img", $(this)).each(function (index) {
                  var imgsSizes = [
                    { w: 1900, h: 600 }
                  ]
                  var src = $(this)
                   .attr("srcset", "")
                   .attr("src")
                   .replace(/\/s[0-9]+/g, "/w" + imgsSizes[index].w + "-h" + imgsSizes[index].h + "-c")
                  $(this).attr("src", src).css("display", "block")
                })
              })
